/// </summary>
/// <returns>active</returns>
int  active()
{
    FormRun   formRun = this.formRun();
    formRun.parmFrmAlternativeDocCursor(null);
    formRun.parmFrmAlternativeDocCursorOrg(null);
    int ret = next active();
    return ret;
}

/// <summary>
/// N.Freidenberger 26.03.2025
/// </summary>
public void init()
{
    next init();
    boolean isCalledFromLP = TradeFormHelper::isCalledFromForm(this.formRun().args(), formStr(SalesQuotationListPage));

    if(isCalledFromLP )
    {
        SalesQuotationTable          callerRecord = this.formRun().args().record();
        SysQuery::findOrCreateRange(this.query().dataSourceTable(tableNum(SalesQuotationTable)),fieldNum(SalesQuotationTable,QuotationId)).value(callerRecord.QuotationId);
    }
}
